     ArrayExpr
   / MapExpr
   / Comprehension
   / a1:LeftEncloser a2:(w StaticArgs)? a3:(w ExprList)? w a4:RightEncloser
     { if (a3 == null) a3 = Collections.<Expr>emptyList();
